# C: arrays and matrices (50 problems). Uses cq() from build-problems-c-control.py.
A = [("arr", "n a")]
A2 = [("arr", "n a"), ("arr", "m b")]
M = [("mat", "r c a")]
T = "Arrays"


def pa(name, count, sep=" "):
    """C code that prints name[0..count-1] on one line."""
    return f'    for (int i = 0; i < {count}; i++) printf("%d%s", {name}[i], i < {count} - 1 ? "{sep}" : "");\n    printf("\\n");'


def pm(name, rows, cols):
    """C code that prints a matrix, one row per line."""
    return f'    for (int i = 0; i < {rows}; i++) {{\n        for (int j = 0; j < {cols}; j++) printf("%d%s", {name}[i][j], j < {cols} - 1 ? " " : "");\n        printf("\\n");\n    }}'


def mt(rows):
    return lines(f"{len(rows)} {len(rows[0])}", *[" ".join(map(str, r)) for r in rows])


def two(a, b):
    return lines(len(a), " ".join(map(str, a))) + lines(len(b), " ".join(map(str, b)))


SORTED = "1 <= n <= 1000"
cq("c-arr-read-print", "Read and Print an Array", "EASY", T, "Read `n` integers into an array and print them on one line, separated by spaces.", "First line `n`, then `n` integers.", "The array.", SORTED,
   pa("a", "n"), [arr([1, 2, 3, 4, 5]), arr([7]), arr([10, -3, 8, 8]), arr(list(range(10))), arr([-1, -2, -3])], A)
