cq("c-arr-intersection", "Intersection of Two Arrays", "MEDIUM", T, "Print the values that appear in both arrays, each once, in the order they first appear in the first array. Print `None` if there are none.", "Line 1 `n`, line 2 the first array, line 3 `m`, line 4 the second array.", "The common values.", "1 <= n, m <= 500",
   '    int out[1000], k = 0;\n    for (int i = 0; i < n; i++) {\n        int inB = 0, seen = 0;\n        for (int j = 0; j < m; j++) if (b[j] == a[i]) inB = 1;\n        for (int j = 0; j < k; j++) if (out[j] == a[i]) seen = 1;\n        if (inB && !seen) out[k++] = a[i];\n    }\n    if (k == 0) printf("None\\n");\n    else {\n        for (int i = 0; i < k; i++) printf("%d%s", out[i], i < k - 1 ? " " : "");\n        printf("\\n");\n    }', [two([1, 2, 3, 4], [3, 4, 5]), two([1, 2], [3, 4]), two([1, 1, 2], [1, 1]), two([5], [5]), two([7, 8, 9], [9, 8, 7])], A2)
cq("c-arr-union", "Union of Two Arrays", "MEDIUM", T, "Print every distinct value that appears in either array: first those of the first array, then the new ones from the second (each in order of first appearance).", "Line 1 `n`, line 2 the first array, line 3 `m`, line 4 the second array.", "The union.", "1 <= n, m <= 500",
   '    int out[1000], k = 0;\n    for (int t = 0; t < n + m; t++) {\n        int v = t < n ? a[t] : b[t - n], seen = 0;\n        for (int j = 0; j < k; j++) if (out[j] == v) seen = 1;\n        if (!seen) out[k++] = v;\n    }\n' + pa("out", "k"), [two([1, 2, 3], [3, 4, 5]), two([1], [1]), two([1, 1, 2], [2, 3]), two([5, 6], [7]), two([9, 8], [8, 9])], A2)
cq("c-arr-negatives-first", "Negatives First", "MEDIUM", T, "Rearrange the array so all negative numbers come first and all other numbers after them. Keep the original order inside each group. Print the result.", "First line `n`, then `n` integers.", "The rearranged array.", SORTED,
   '    int out[1000], k = 0;\n    for (int i = 0; i < n; i++) if (a[i] < 0) out[k++] = a[i];\n    for (int i = 0; i < n; i++) if (a[i] >= 0) out[k++] = a[i];\n' + pa("out", "k"), [arr([1, -2, 3, -4, 5]), arr([7]), arr([-1, -2]), arr([0, -1, 2, -3]), arr([4, 5, 6])], A)

